window.CARDS=window.CARDS||{};CARDS["people-amikura-mako"]=[{"i":"sc-amikura-mako-y1v9-p82-1","v":"y1v9","y":1,"o":11,"k":"spoken","w":"ichinose-honami amikura-mako","q":"amikura mako hugging ichinose in the lobby class b girl approaches as ichinose reads the letter and hugs her   this is in the mailboxes   yeah  it s terrible  isn t it  it s probably in every first year mailbox  pleads with her to go to the teachers    hey  you don t need to put up with this anymore   y you have to  if you don t  the horrible rumors about honami chan are going to spread everywhere  part of the class b group desperately trying to move ichinose to report the letter","h":"<article class=\"card\" id=\"sc-amikura-mako-y1v9-p82-1\"><h3><span class=\"ttl\">Hugging Ichinose in the lobby<\/span><span class=\"meta\">Y1V9 · p.82–83<\/span><\/h3><p class=\"setup\">Class B girl approaches as Ichinose reads the letter and hugs her.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“…This is in the mailboxes?”<span class=\"pg\">p.82<\/span><\/li><li class=\"q spoken\">“Yeah… It’s terrible, isn’t it? It’s probably in every first-year mailbox…”<span class=\"pg\">p.82<\/span><\/li><li class=\"q spoken\">“Y-You have to! If you don’t, the horrible rumors about Honami-chan are going to spread everywhere!”<span class=\"pg\">p.82<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Pleads with her to go to the teachers — “Hey, you don’t need to put up with this anymore.”<span class=\"pg\">p.82–83<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Part of the Class B group desperately trying to move Ichinose to report the letter.<span class=\"pg\">p.83<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y1v9-p171-1\">→ After: At Ichinose’s side in the confession<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y1v9-p171-1","v":"y1v9","y":1,"o":11,"k":"spoken","w":"ichinose-honami amikura-mako","q":"amikura mako at ichinose s side in the confession named at ichinose s side when ichinose asks her and chihiro for space   honami chan  a shoplifter  r really  ichinose answers her by name  yes  and she is sorry","h":"<article class=\"card\" id=\"sc-amikura-mako-y1v9-p171-1\"><h3><span class=\"ttl\">At Ichinose’s side in the confession<\/span><span class=\"meta\">Y1V9 · p.171–172<\/span><\/h3><p class=\"setup\">Named at Ichinose’s side when Ichinose asks her and Chihiro for space.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Honami-chan… a shoplifter…? R-really?”<span class=\"pg\">p.172<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Ichinose answers her by name: yes, and she is sorry.<span class=\"pg\">p.172<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y1v9-p82-1\">← Before: Hugging Ichinose in the lobby<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y1v11_75-p15-1","v":"y1v11.75","y":1,"o":15,"k":"","w":"ichinose-honami shiranami-chihiro amikura-mako","q":"amikura mako short story  keyaki mall meetup mako chan meets ichinose and chihiro chan at keyaki mall on the last day of spring break  she asks ichinose whether she is feeling well after ichinose spent much of the break alone  meets her and checks on her at keyaki mall  meets with her and ichinose","h":"<article class=\"card\" id=\"sc-amikura-mako-y1v11_75-p15-1\"><h3><span class=\"ttl\">Short story: Keyaki mall meetup<\/span><span class=\"meta\">Y1V11.75 · p.15<\/span><\/h3><p class=\"setup\">Mako-chan meets Ichinose and Chihiro-chan at Keyaki mall on the last day of spring break. She asks Ichinose whether she is feeling well after Ichinose spent much of the break alone.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"shiranami-chihiro.html\">Shiranami Chihiro<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Meets her and checks on her at Keyaki mall.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiranami Chihiro<\/b> Meets with her and Ichinose.<span class=\"pg\">p.15<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amikura-mako-y2v2-p168-1","v":"y2v2","y":2,"o":17,"k":"","w":"amikura-mako","q":"amikura mako named in passing  ch 3  amikura mako   roster twin of asakura mako for the same class c student  the corpus prints  asakura mako  at p 168 as the more people card holder  scenes tracked on asakura mako md  flagged as a duplicate roster row for the owner  do not merge from this side","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v2-p168-1\"><h3><span class=\"ttl\">Named in passing (Ch.3)<\/span><span class=\"meta\">Y2V2 · p.168<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Amikura Mako — roster twin of asakura-mako for the same Class C student; the corpus prints “Asakura Mako” at p.168 as the More People card holder; scenes tracked on asakura-mako.md; flagged as a duplicate roster row for the owner, do not merge from this side.<span class=\"pg\">p.168<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amikura-mako-y2v4_5-p61-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"amikura-mako","q":"amikura mako amikura hosts the girls  exam celebration party as host of the gathering in room 5034  she calls for order and toasts   so  without further ado we re having a party to celebrate the end of the uninhabited island exam and also to thank ayanokoji kun for helping chihiro chan when she was lost  cheers  ten girls  half of ichinose s class  all in one room   she appears to be the organizer  most participants are girls ayanokoji never spoke to before  he knows them only from the oaa app","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v4_5-p61-1\"><h3><span class=\"ttl\">Amikura hosts the girls&#x27; exam-celebration party<\/span><span class=\"meta\">Y2V4.5 · p.61<\/span><\/h3><p class=\"setup\">As host of the gathering in room 5034, she calls for order and toasts: “So, without further ado…We&#x27;re having a party to celebrate the end of the uninhabited island exam and also to thank Ayanokōji-kun for helping Chihiro-chan when she was lost. Cheers!”<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Ten girls, half of Ichinose&#x27;s class, all in one room — she appears to be the organizer; most participants are girls Ayanokōji never spoke to before (he knows them only from the OAA app).<span class=\"pg\">p.60–61<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amikura-mako-y2v8-p11-1","v":"y2v8","y":2,"o":24,"k":"","w":"amikura-mako","q":"amikura mako amikura mako mentioned in passing named in this volume  passing mentions on pages  p 46 47  p 49 50  p 67  p 79  p 83  passing mention only","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v8-p11-1\"><h3><span class=\"ttl\">amikura-mako mentioned in passing<\/span><span class=\"meta\">Y2V8 · p.11-208<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: p.46-47, p.49-50, p.67, p.79, p.83.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v8-p46-1\">→ After: Group 6: the nervous girl<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v8-p46-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"watanabe-norihito kushida-kikyou nishino-takeko yamamura-miki amikura-mako","q":"amikura mako group 6  the nervous girl boards on the class d bus  her name closes group 6  ayanokoji s private numbering  amikura   14  she waves alongside watanabe  she and kushida rejoice visibly at landing in the same group   they took each other s hands and rejoiced at being in the same group  she makes friends easily where yamamura cannot  she whispers to the other girls  nervous  i m a little nervous thinking about a boy s room  she nearly intervenes in the ryuen kito futon feud  she mutters at the pillow fight  she says  this is still  a pillow fight  right   i m a little nervous thinking about a boy s room   this is still  a pillow fight  right  on tomorrow s plan  she concedes skiing because she doesn t want to be the holdout  she swallows her unease and defers to the group   we re a group  sweet but easily unsettled  better around girls  she defers to group harmony even at her own discomfort  her class d groupmate  they re friendly  kushida guides her through the trip  nishino reins her in at the futon dispute  group 6","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v8-p46-1\"><h3><span class=\"ttl\">Group 6: the nervous girl<\/span><span class=\"meta\">Y2V8 · p.46–88<\/span><\/h3><p class=\"setup\">Boards on the Class D bus; her name closes group 6. She waves alongside Watanabe; she and Kushida rejoice visibly at landing in the same group — they took each other&#x27;s hands and rejoiced at being in the same group; she makes friends easily where Yamamura cannot. She whispers to the other girls, nervous (&quot;I&#x27;m a little nervous thinking about a boy&#x27;s room.&quot;); she nearly intervenes in the Ryūen–Kitō futon feud; she mutters at the pillow fight; she says “This is still… a pillow fight, right?” On tomorrow&#x27;s plan: she concedes skiing because she doesn&#x27;t want to be the holdout; she swallows her unease and defers to the group.<\/p><p class=\"with\">with <a href=\"watanabe-norihito.html\">Watanabe Norihito<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"nishino-takeko.html\">Nishino Takeko<\/a> · <a href=\"yamamura-miki.html\">Yamamura Miki<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I&#x27;m a little nervous thinking about a boy&#x27;s room.”<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\">“This is still… a pillow fight, right?”<span class=\"pg\">p.85<\/span><\/li><li class=\"q spoken\">“We&#x27;re a group.”<span class=\"pg\">p.88<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Ayanokōji&#x27;s private numbering: Amikura = 14.<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Sweet but easily unsettled; better around girls; she defers to group harmony even at her own discomfort.<span class=\"pg\">p.46–88<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Watanabe Norihito<\/b> Her Class D groupmate.<span class=\"pg\">p.46, 49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> They&#x27;re friendly; Kushida guides her through the trip.<span class=\"pg\">p.49–79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> Nishino reins her in at the futon dispute.<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamamura Miki<\/b> Group 6.<span class=\"pg\">p.46<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v8-p11-1\">← Before: amikura-mako mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v8-p92-1\">→ After: The snowman girl; the quiet climb<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v8-p92-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"nishino-takeko yamamura-miki kushida-kikyou watanabe-norihito amikura-mako","q":"amikura mako the snowman girl  the quiet climb the bus runs late  she proposes building a snowman to pass the time  she s the spark for the morning s only wholesome event   hey  hey  since it s a special occasion  why don t we all build a snowman  she s the first to rally the group to browse the shops  most are closed  she walks ahead  she doesn t notice yamamura s absence   let s all go browse more shops  she signs up for the beginner course despite being able to ski normally   she will not leave yamamura behind  she volunteers to support her openly   oh  that s okay  kushida san  i ll do it in the beginner s area  they skied the same slow line together  she protects her without making it weird  they agree without words  snowman co conspirator","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v8-p92-1\"><h3><span class=\"ttl\">The snowman girl; the quiet climb<\/span><span class=\"meta\">Y2V8 · p.92–104<\/span><\/h3><p class=\"setup\">The bus runs late; she proposes building a snowman to pass the time; she&#x27;s the spark for the morning&#x27;s only wholesome event. She&#x27;s the first to rally the group to browse the shops (most are closed); she walks ahead; she doesn&#x27;t notice Yamamura&#x27;s absence. She signs up for the beginner course despite being able to ski normally — she will not leave Yamamura behind; she volunteers to support her openly.<\/p><p class=\"with\">with <a href=\"nishino-takeko.html\">Nishino Takeko<\/a> · <a href=\"yamamura-miki.html\">Yamamura Miki<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"watanabe-norihito.html\">Watanabe Norihito<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hey, hey, since it&#x27;s a special occasion, why don&#x27;t we all build a snowman?”<span class=\"pg\">p.92<\/span><\/li><li class=\"q spoken\">“Let&#x27;s all go browse more shops.”<span class=\"pg\">p.97<\/span><\/li><li class=\"q spoken\">“Oh, that&#x27;s okay, Kushida-san. I&#x27;ll do it in the beginner&#x27;s area.”<span class=\"pg\">p.103<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> They skied the same slow line together.<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamamura Miki<\/b> She protects her without making it weird.<span class=\"pg\">p.103–104<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> They agree without words.<span class=\"pg\">p.103–104<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Watanabe Norihito<\/b> Snowman co-conspirator.<span class=\"pg\">p.92<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v8-p46-1\">← Before: Group 6: the nervous girl<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v8-p108-1\">→ After: Passing-mention records<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v8-p108-1","v":"y2v8","y":2,"o":24,"k":"","w":"amikura-mako","q":"amikura mako passing mention records  i ve learned to ski pretty well  i m still not as good as amikura and nishino  though   watanabe  rating himself   i instructed kushida  amikura  and watanabe not to move   ayanokoji  holding the group back during the gifu incident   my bad  it s not really a coincidence  amikura and the others were making a fuss that they couldn t find you   kushida san  nishino san  amikura san and everyone in the group watched me and saw me as a companion   yamamura s ss credit","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v8-p108-1\"><h3><span class=\"ttl\">Passing-mention records<\/span><span class=\"meta\">Y2V8 · p.108, 114, 187, 200<\/span><\/h3><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> &quot;I&#x27;ve learned to ski pretty well. I&#x27;m still not as good as Amikura and Nishino, though.&quot; (Watanabe, rating himself)<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;I instructed Kushida, Amikura, and Watanabe not to move.&quot; (Ayanokōji, holding the group back during the Gifu incident)<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;My bad, it&#x27;s not really a coincidence. Amikura and the others were making a fuss that they couldn’t find you.&quot;<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;Kushida-san, Nishino-san, Amikura-san and everyone in the group watched me and saw me as a companion.&quot; (Yamamura&#x27;s SS credit)<span class=\"pg\">p.200<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v8-p92-1\">← Before: The snowman girl; the quiet climb<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v8-p130-1\">→ After: The tour debate; the silent satirist<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v8-p130-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"watanabe-norihito kushida-kikyou kitou-hayato amikura-mako","q":"amikura mako the tour debate  the silent satirist she fumbles the map app  typing destinations at random  she funny looks ayanokoji after watanabe s karuizawa dig  she sidles behind the majority  she wants no fight   hmm  even if i tried to give a route on a map app  i wouldn t even know where things are  so the order would be messed up  they exchange cowardly conspicuous glances after the karuizawa quip  she defers to kushida s strategy  barely involved  he chooses the same side  she s relieved","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v8-p130-1\"><h3><span class=\"ttl\">The tour debate; the silent satirist<\/span><span class=\"meta\">Y2V8 · p.130–139<\/span><\/h3><p class=\"setup\">She fumbles the map app (typing destinations at random); she funny-looks Ayanokōji after Watanabe&#x27;s Karuizawa dig; she sidles behind the majority; she wants no fight.<\/p><p class=\"with\">with <a href=\"watanabe-norihito.html\">Watanabe Norihito<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"kitou-hayato.html\">Kitō Hayato<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hmm. Even if I tried to give a route on a map app, I wouldn&#x27;t even know where things are, so the order would be messed up.”<span class=\"pg\">p.132<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Watanabe Norihito<\/b> They exchange cowardly-conspicuous glances after the Karuizawa quip.<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> She defers to Kushida&#x27;s strategy, barely involved.<span class=\"pg\">p.135–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> He chooses the same side; she&#x27;s relieved.<span class=\"pg\">p.133–139<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v8-p108-1\">← Before: Passing-mention records<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v8-p162-1\">→ After: The morning crowd; the missing girl report<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v8-p162-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"ichinose-honami watanabe-norihito kushida-kikyou amikura-mako","q":"amikura mako the morning crowd  the missing girl report she tags along to the fight  she doesn t throw either  she s thrilled by the spectacle  she exchanges a look with watanabe at the boys v boys chaos  they re conspirators in spectate only mode  after the fight  she bursts into the lobby  honami s missing  the group is scouring the inn  she takes the news hard  she asks ayanokoji to find her   look  the school trip is over already  right  so we decided to get together with everyone in the class and chat until lights out  but we couldn t find honami  so we were worried   i heard that she looked distressed in the evening  so i was a little worried  she reports her missing  she pulls everyone into the search  the fight couple of the mind  they watch together  she tags along with her","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v8-p162-1\"><h3><span class=\"ttl\">The morning crowd; the missing girl report<\/span><span class=\"meta\">Y2V8 · p.162–174, 185–186<\/span><\/h3><p class=\"setup\">She tags along to the fight; she doesn&#x27;t throw either; she&#x27;s thrilled by the spectacle. She exchanges a look with Watanabe at the boys&#x27;-v-boys chaos; they&#x27;re conspirators in spectate-only mode. After the fight, she bursts into the lobby: Honami&#x27;s missing; the group is scouring the inn; she takes the news hard; she asks Ayanokōji to find her.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"watanabe-norihito.html\">Watanabe Norihito<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Look, the school trip is over already, right? So we decided to get together with everyone in the class and chat until lights out, but we couldn&#x27;t find Honami, so we were worried.”<span class=\"pg\">p.185<\/span><\/li><li class=\"q spoken\">“I heard that she looked distressed in the evening... so I was a little worried.”<span class=\"pg\">p.185<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> She reports her missing; she pulls everyone into the search.<span class=\"pg\">p.185–186<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Watanabe Norihito<\/b> The fight couple-of-the-mind; they watch together.<span class=\"pg\">p.162–164<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> She tags along with her.<span class=\"pg\">p.162–174<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v8-p130-1\">← Before: The tour debate; the silent satirist<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v9-p95-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"ichinose-honami ayanokouji-kiyotaka kanzaki-ryuuji amikura-mako","q":"amikura mako amikura  secret keeper  gym witness  and friend at the karaoke meeting she is one of the two let into kanzaki s secret plan  she voices reservations about keeping it from ichinose and is reassured it is a gamble   i don t mind being trusted  but  at the gym she runs into ichinose and ayanokoji  is surprised  and quietly reads the situation   noting ayanokoji and the gym do not fit together and later teasing ichinose   oh  mako chan  good morning   w what are you doing at the gym   this is your first time in a gym  right  take it easy  ayanokouji kun  loyal and observant   trusted with a dangerous secret  careful about how it is used  and perceptive enough to notice the chemistry between her best friend and ayanokoji  her best friend  honami chan  surprised to find her at the gym with ayanokoji  teases him for being out of place at the gym  let into his secret plan to help ichinose s class","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v9-p95-1\"><h3><span class=\"ttl\">Amikura: secret-keeper, gym witness, and friend<\/span><span class=\"meta\">Y2V9 · p.95–97, 124–129<\/span><\/h3><p class=\"setup\">At the karaoke meeting she is one of the two let into Kanzaki&#x27;s secret plan; she voices reservations about keeping it from Ichinose and is reassured it is a gamble. At the gym she runs into Ichinose and Ayanokōji, is surprised, and quietly reads the situation — noting Ayanokōji and the gym do not fit together and later teasing Ichinose.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I don&#x27;t mind being trusted, but...&quot;<span class=\"pg\">p.95<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;Oh, Mako-chan, good morning!&quot;<span class=\"pg\">p.124<\/span><\/li><li class=\"q spoken\">&quot;W-what are you doing at the gym?&quot;<span class=\"pg\">p.125<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;This is your first time in a gym, right? Take it easy, Ayanokouji-kun.&quot;<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Loyal and observant — trusted with a dangerous secret, careful about how it is used, and perceptive enough to notice the chemistry between her best friend and Ayanokōji.<span class=\"pg\">p.95–129<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Her best friend (&quot;Honami-chan&quot;); surprised to find her at the gym with Ayanokōji.<span class=\"pg\">p.124–129<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Teases him for being out of place at the gym.<span class=\"pg\">p.125–126<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Let into his secret plan to help Ichinose&#x27;s class.<span class=\"pg\">p.95–97<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amikura-mako-y2v9_5-p19-1","v":"y2v9.5","y":2,"o":26,"k":"","w":"amikura-mako","q":"amikura mako amikura mentioned in passing named in this volume  passing mention  locator pages  p 19  p 32  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v9_5-p19-1\"><h3><span class=\"ttl\">Amikura mentioned in passing<\/span><span class=\"meta\">Y2V9.5 · p.19-32<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.19, p.32; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.19<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amikura-mako-y2v10-p9-1","v":"y2v10","y":2,"o":28,"k":"","w":"amikura-mako","q":"amikura mako amikura mako mentioned in passing named in this volume  passing mention  locator pages  p 107 109  p 117  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10-p9-1\"><h3><span class=\"ttl\">amikura-mako mentioned in passing<\/span><span class=\"meta\">Y2V10 · p.9-235<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.107-109, p.117; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.9<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10-p107-1\">→ After: Ch.5: The fourth seat<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10-p107-1","v":"y2v10","y":2,"o":28,"k":"spoken","w":"ichinose-honami watanabe-norihito kanzaki-ryuuji amikura-mako","q":"amikura mako ch 5  the fourth seat she arrives with ichinose and kanzaki carrying snacks  sits by ichinose  her silence reads as patience  she expected neither the phone story nor the door   the special exam is tomorrow  right  isn t it too late to push for the four classes to collude now   if the four classes could coordinate and ensure a clear victory  her suggestion is worth considering  even if we lose class points  as long as all classes   face the same fate  it wouldn t be unfair  as kanzaki kun said  it might still be possible to realize that plan  she watches the gathering dissolve  she keeps her own counsel as the guests leave past six  she came as watanabe s plausible cover story s fourth presence   no one asks her to confirm anything  best friend  she knows what the  repulsive  remark means and mischievously enjoys it  he likes mako chan  she is aware  she hears everything  she agrees publicly with the coordination logic  he is relieved to find an ally","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10-p107-1\"><h3><span class=\"ttl\">Ch.5: The fourth seat<\/span><span class=\"meta\">Y2V10 · p.107–109<\/span><\/h3><p class=\"setup\">She arrives with Ichinose and Kanzaki carrying snacks; sits by Ichinose; her silence reads as patience; she expected neither the phone story nor the door. She watches the gathering dissolve; she keeps her own counsel as the guests leave past six.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"watanabe-norihito.html\">Watanabe Norihito<\/a> · <a href=\"kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“The special exam is tomorrow, right? Isn’t it too late to push for the four classes to collude now?”<span class=\"pg\">p.108<\/span><\/li><li class=\"q spoken\">“If the four classes could coordinate and ensure a clear victory, her suggestion is worth considering. Even if we lose class points, as long as all classes”<span class=\"pg\">p.108<\/span><\/li><li class=\"q spoken\">“face the same fate, it wouldn’t be unfair. As Kanzaki-kun said, it might still be possible to realize that plan.”<span class=\"pg\">p.109<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> She came as Watanabe&#x27;s plausible cover story&#x27;s fourth presence — no one asks her to confirm anything.<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Best friend; she knows what the &quot;repulsive&quot; remark means and mischievously enjoys it.<span class=\"pg\">p.107–109<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Watanabe Norihito<\/b> He likes Mako-chan; she is aware; she hears everything.<span class=\"pg\">p.106–109<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> She agrees publicly with the coordination logic; he is relieved to find an ally.<span class=\"pg\">p.108<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10-p9-1\">← Before: amikura-mako mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10-p117-1\">→ After: Ch.5: passing mentions (locator cross-check)<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10-p117-1","v":"y2v10","y":2,"o":28,"k":"","w":"amikura-mako","q":"amikura mako ch 5  passing mentions  locator cross check  passing mention   what did amikura look like today  was she watching me  was my story","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10-p117-1\"><h3><span class=\"ttl\">Ch.5: passing mentions (locator cross-check)<\/span><span class=\"meta\">Y2V10 · p.117–117<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Passing mention — What did Amikura look like today? Was she watching me? Was my story<span class=\"pg\">p.117<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10-p107-1\">← Before: Ch.5: The fourth seat<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p1-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"ichinose-honami ayanokouji-kiyotaka amikura-mako","q":"amikura mako arrival at the gym and the exam questions arrives at the gym with ichinose during the first break after the survival and elimination exam and finds ayanokoji in the rest area looking at a red panda article   oh  that s a cute photo  it s a red panda  right   is that really the problem  these things garnered quite a buzz on the internet too  didn t they  light and needling  she takes the red panda photo as an opening  then doubts his not watching tv excuse instead of accepting it  the page repeats a clause    amikura expressed her doubt  perhaps my not watching tv excuse wasn t persuasive enough  amikura expressed her doubt    kept as printed  comes to the gym with her  gym acquaintance  teases him about the questions he missed","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p1-1\"><h3><span class=\"ttl\">Arrival at the gym and the exam questions<\/span><span class=\"meta\">Y2V10.25 · p.1–2<\/span><\/h3><p class=\"setup\">Arrives at the gym with Ichinose during the first break after the survival and elimination exam and finds Ayanokōji in the rest area looking at a red-panda article.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Oh, that’s a cute photo. It’s a red panda, right?”<span class=\"pg\">p.1<\/span><\/li><li class=\"q spoken\">“Is that really the problem? These things garnered quite a buzz on the internet too, didn’t they?”<span class=\"pg\">p.2<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Voice<\/span> Light and needling: she takes the red-panda photo as an opening, then doubts his not-watching-TV excuse instead of accepting it.<span class=\"pg\">p.1–2<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The page repeats a clause — “Amikura expressed her doubt; perhaps my not-watching-TV excuse wasn’t persuasive enough, Amikura expressed her doubt.” — kept as printed.<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Comes to the gym with her.<span class=\"pg\">p.1<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Gym acquaintance; teases him about the questions he missed.<span class=\"pg\">p.1–2<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p2-1\">→ After: The change in Honami<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p2-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako","q":"amikura mako the change in honami with ichinose called to the counter by akiyama over a paperwork mistake  she sits down beside ayanokoji and opens the subject of how ichinose has changed   honami chan s really changed  huh  it s like  unimaginable from a few months  ago  the line runs across the page break and the print leaves it untagged  the next speech tag comes on p 3 with  amikura began to speak  recorded in the volume s unattributed list   it was right after the second year deserted island exam ended  and the second semester had just started  i think   back then  honami chan seemed unstable  or rather  she was often lost in thought   right around that time  a little incident happened in the class  oh  but keep this story between us  okay  don t tell honami chan  treats the story as a confidence with responsibility attached  she asks for secrecy before she tells it","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p2-1\"><h3><span class=\"ttl\">The change in Honami<\/span><span class=\"meta\">Y2V10.25 · p.2–3<\/span><\/h3><p class=\"setup\">With Ichinose called to the counter by Akiyama over a paperwork mistake, she sits down beside Ayanokōji and opens the subject of how Ichinose has changed.<\/p><ul class=\"lines\"><li class=\"q spoken\">“Honami-chan’s really changed, huh? It’s like, unimaginable from a few months… ago…”<span class=\"pg\">p.2<\/span><\/li><li class=\"q spoken\">“It was right after the second-year deserted island exam ended, and the second semester had just started, I think.”<span class=\"pg\">p.3<\/span><\/li><li class=\"q spoken\">“Back then, Honami-chan seemed unstable, or rather, she was often lost in thought.”<span class=\"pg\">p.3<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The line runs across the page break and the print leaves it untagged; the next speech tag comes on p.3 with “Amikura began to speak”. Recorded in the volume’s unattributed list.<span class=\"pg\">p.2–3<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Right around that time, a little incident happened in the class… Oh, but keep this story between us, okay? Don’t tell Honami-chan.”<span class=\"pg\">p.3<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Treats the story as a confidence with responsibility attached; she asks for secrecy before she tells it.<span class=\"pg\">p.3<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p1-1\">← Before: Arrival at the gym and the exam questions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p3-1\">→ After: The misdirected message<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p3-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"ishizaki-daichi ichinose-honami amikura-mako","q":"amikura mako the misdirected message explains the origin of the rumor  a message ichinose sent by mistake during an unstable spell after the deserted island exam   i didn t see the text myself  but i think it was something like   i want to calm down and talk  can we meet in person  taken out of context  it sounds quite meaningful  right   different class  but the problem lies in who she accidentally sent it to  that person was ishizaki kun  and during the break  he came to our class and boldly asked   what does this message mean  while showing the screen   honami chan was flustered but immediately corrected it  saying it was a misdirected message  ishizaki kun was convinced and went back to his class  but the difficulty was what followed  the fact that it was a missent message meant that she intended to send that important message to someone else  names him as the accidental recipient who carried the screen into ichinose s class  keeps her confidence and tells the story without blaming her for the mistake","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p3-1\"><h3><span class=\"ttl\">The misdirected message<\/span><span class=\"meta\">Y2V10.25 · p.3–4<\/span><\/h3><p class=\"setup\">Explains the origin of the rumor: a message Ichinose sent by mistake during an unstable spell after the deserted island exam.<\/p><p class=\"with\">with <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I didn’t see the text myself, but I think it was something like, ‘I want to calm down and talk. Can we meet in person?’ Taken out of context, it sounds quite meaningful, right?”<span class=\"pg\">p.3<\/span><\/li><li class=\"q spoken\">“Different class. But the problem lies in who she accidentally sent it to. That person was Ishizaki-kun, and during the break, he came to our class and boldly asked, ‘What does this message mean?’ while showing the screen.”<span class=\"pg\">p.4<\/span><\/li><li class=\"q spoken\">“Honami-chan was flustered but immediately corrected it, saying it was a misdirected message. Ishizaki-kun was convinced and went back to his class, but the difficulty was what followed. The fact that it was a missent message…”<span class=\"pg\">p.4<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Honami-chan was flustered but immediately corrected it, saying it was a misdirected message. Ishizaki-kun was convinced and went back to his class, but the difficulty was what followed. The fact that it was a missent message meant that she intended to send that important message to someone else.”<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Names him as the accidental recipient who carried the screen into Ichinose’s class.<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Keeps her confidence and tells the story without blaming her for the mistake.<span class=\"pg\">p.3–4<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p2-1\">← Before: The change in Honami<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p4-1\">→ After: The alphabet and the freeze<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p4-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"ichinose-honami amikura-mako","q":"amikura mako the alphabet and the freeze lays out why the class settled on ayanokoji  the contact list s alphabetical order puts his  a  next to ishizaki s  i   you d understand if you saw it  right   well  that s limited to those with sharp intuition  the boys started making noise for a different reason  ayanokoji kun  maybe it s because your  a  and ishizakikun s  i  are close in the contact list  which is arranged in alphabetical order  there are other names close by  but you and honami chan are often seen together   ishizakikun  prints without a hyphen or space   kept as printed  a translator s note printed on the page explains the japanese gojuon ordering that places   and   together   honami chan is always bright and composed  but she gets quite flustered when it comes to matters concerning herself  maybe she couldn t come up with a good excuse at that time  and she turned pale with her eyes drawn to the floor   catching sight of the scene  from our point of view  it was very rare to see honami chan like that   we were watching over her for a while  but it gradually started to feel heavy  boys who didn t think it was you started to wonder if she was planning to confess to someone  reads her public composure as a mask that fails when the matter is personal  the page prints an unlabelled first person inset on ichinose s dilemma before amikura resumes  the inset is recorded in the volume notes  not attributed to a speaker","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p4-1\"><h3><span class=\"ttl\">The alphabet and the freeze<\/span><span class=\"meta\">Y2V10.25 · p.4–5<\/span><\/h3><p class=\"setup\">Lays out why the class settled on Ayanokōji: the contact list’s alphabetical order puts his “A” next to Ishizaki’s “I”.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“You’d understand if you saw it, right?”<span class=\"pg\">p.4<\/span><\/li><li class=\"q spoken\">“Well, that’s limited to those with sharp intuition… The boys started making noise for a different reason. Ayanokōji-kun, maybe it’s because your ‘A’ and Ishizakikun’s ‘I’ are close in the contact list, which is arranged in…”<span class=\"pg\">p.4<\/span><\/li><li class=\"q spoken\">“Honami-chan is always bright and composed, but she gets quite flustered when it comes to matters concerning herself. Maybe she couldn’t come up with a good excuse at that time, and she turned pale with her eyes drawn to the…”<span class=\"pg\">p.4<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Well, that’s limited to those with sharp intuition… The boys started making noise for a different reason. Ayanokōji-kun, maybe it’s because your ‘A’ and Ishizakikun’s ‘I’ are close in the contact list, which is arranged in alphabetical order. There are other names close by, but you and Honami-chan are often seen together…”<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Ishizakikun” prints without a hyphen or space — kept as printed.<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> A translator’s note printed on the page explains the Japanese gojūon ordering that places あ and い together.<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Honami-chan is always bright and composed, but she gets quite flustered when it comes to matters concerning herself. Maybe she couldn’t come up with a good excuse at that time, and she turned pale with her eyes drawn to the floor.”<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Catching sight of the scene, from our point of view, it was very rare to see Honami-chan like that.”<span class=\"pg\">p.5<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We were watching over her for a while, but it gradually started to feel heavy. Boys who didn’t think it was you started to wonder if she was planning to confess to someone.”<span class=\"pg\">p.5<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Reads her public composure as a mask that fails when the matter is personal.<span class=\"pg\">p.4–5<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The page prints an unlabelled first-person inset on Ichinose’s dilemma before Amikura resumes; the inset is recorded in the volume notes, not attributed to a speaker.<span class=\"pg\">p.5<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p3-1\">← Before: The misdirected message<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p6-1\">→ After: The girls’ rescue and the thanks<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p6-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako","q":"amikura mako the girls  rescue and the thanks describes how the girls closed ranks  they knew the intended recipient and protected her privacy   like me  the girls knew who honami chan intended to send it to  we secretly discussed how to help and stepped in to support her  the intended recipient was a girl who had sought love advice from ichinose  ichinose s silence protected that girl   there was nothing to do but accept it  right  the print leaves this line untagged  recorded in the volume s unattributed list   i didn t do anything special  ichinose just recovered with her own strength   thanking someone who did nothing  deflects credit for the rescue onto ichinose and the group rather than claiming a hand in it","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p6-1\"><h3><span class=\"ttl\">The girls’ rescue and the thanks<\/span><span class=\"meta\">Y2V10.25 · p.6–7<\/span><\/h3><p class=\"setup\">Describes how the girls closed ranks: they knew the intended recipient and protected her privacy.<\/p><ul class=\"lines\"><li class=\"q spoken\">“Like me, the girls knew who Honami-chan intended to send it to. We secretly discussed how to help and stepped in to support her.”<span class=\"pg\">p.6<\/span><\/li><li class=\"q spoken\">“There was nothing to do but accept it, right?”<span class=\"pg\">p.7<\/span><\/li><li class=\"q spoken\">“I didn’t do anything special. Ichinose just recovered with her own strength.”<span class=\"pg\">p.7<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The intended recipient was a girl who had sought love advice from Ichinose; Ichinose’s silence protected that girl.<span class=\"pg\">p.6<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The print leaves this line untagged; recorded in the volume’s unattributed list.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thanking someone who did nothing?”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Deflects credit for the rescue onto Ichinose and the group rather than claiming a hand in it.<span class=\"pg\">p.6–7<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p4-1\">← Before: The alphabet and the freeze<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p7-1\">→ After: The warning<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p7-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami amikura-mako","q":"amikura mako the warning turns from the past to the present  she tells ayanokoji that ichinose still sees him as someone special and asks him not to hurt her   no  it s a different matter   you can tell if you look  but even now  honami chan sees you as someone very special  you re the only one in this school who can have a strong influence on her  that s why   i m telling you this because  i don t want you to make honami chan sad or hurt her   right   of course  i understand your position  it s not about whether you re dating or not  i just don t want her to be unnecessarily hurt   it s tough for honamichan  falling for a guy who has a girlfriend   honamichan  prints without a hyphen   kept as printed   i have a vague idea of you too  i figure you aren t flustered  right  reads him as unflustered and says so  asks him plainly not to hurt ichinose  her best friend  she can see ichinose s feelings and acts on them without speaking for her","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p7-1\"><h3><span class=\"ttl\">The warning<\/span><span class=\"meta\">Y2V10.25 · p.7<\/span><\/h3><p class=\"setup\">Turns from the past to the present: she tells Ayanokōji that Ichinose still sees him as someone special and asks him not to hurt her.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“No, it’s a different matter.”<span class=\"pg\">p.7<\/span><\/li><li class=\"q spoken\">“You can tell if you look, but even now, Honami-chan sees you as someone very special. You’re the only one in this school who can have a strong influence on her, that’s why.”<span class=\"pg\">p.7<\/span><\/li><li class=\"q spoken\">“I’m telling you this because… I don’t want you to make Honami-chan sad or hurt her.”<span class=\"pg\">p.7<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Right,”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course, I understand your position. It’s not about whether you’re dating or not. I just don’t want her to be unnecessarily hurt.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s tough for Honamichan, falling for a guy who has a girlfriend.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Honamichan” prints without a hyphen — kept as printed.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have a vague idea of you too. I figure you aren’t flustered, right?”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reads him as unflustered and says so; asks him plainly not to hurt Ichinose.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Her best friend; she can see Ichinose’s feelings and acts on them without speaking for her.<span class=\"pg\">p.7<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p6-1\">← Before: The girls’ rescue and the thanks<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p8-1\">→ After: The terms and the goodbye<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p8-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako","q":"amikura mako the terms and the goodbye accepts his answer without pressing  apologizes for speaking as a third party  and covers her embarrassment when ichinose returns   i m sorry  it s not my place to tell you this as a third party  the print leaves  sorry to keep you both waiting  and  no  not at all  untagged  the first follows  ichinose returned  the second follows the narration of amikura s momentary fluster  both are listed in the volume s unattributed lines   no  not at all  blunt but careful  she states the hard request  then immediately concedes she has no standing to make it  leaves the story as ichinose s best friend who has said her piece  no further scene","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p8-1\"><h3><span class=\"ttl\">The terms and the goodbye<\/span><span class=\"meta\">Y2V10.25 · p.8–9<\/span><\/h3><p class=\"setup\">Accepts his answer without pressing, apologizes for speaking as a third party, and covers her embarrassment when Ichinose returns.<\/p><ul class=\"lines\"><li class=\"q spoken\">“I’m sorry, it’s not my place to tell you this as a third party.”<span class=\"pg\">p.8<\/span><\/li><li class=\"q spoken\">“No, not at all.”<span class=\"pg\">p.8<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The print leaves “Sorry to keep you both waiting,” and “No, not at all.” untagged; the first follows “Ichinose returned”, the second follows the narration of Amikura’s momentary fluster. Both are listed in the volume’s unattributed lines.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Voice<\/span> Blunt but careful: she states the hard request, then immediately concedes she has no standing to make it.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Leaves the story as Ichinose’s best friend who has said her piece; no further scene.<span class=\"pg\">p.9<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p7-1\">← Before: The warning<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v12-p12-1","v":"y2v12","y":2,"o":31,"k":"","w":"amikura-mako","q":"amikura mako amikura mako mentioned in passing named in this volume  passing mention  locator pages  p 157  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v12-p12-1\"><h3><span class=\"ttl\">amikura-mako mentioned in passing<\/span><span class=\"meta\">Y2V12 · p.12-228<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.157; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amikura-mako-y2v12_5-p177-1","v":"y2v12.5","y":2,"o":32,"k":"","w":"ayanokouji-kiyotaka amikura-mako","q":"amikura mako ch 9 mentioned appears in ch 9  appears in this volume","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v12_5-p177-1\"><h3><span class=\"ttl\">Ch.9<\/span><span class=\"meta\">Y2V12.5 · p.177-191<\/span><\/h3><p class=\"setup\">Mentioned/appears in Ch.9.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Appears in this volume.<span class=\"pg\">p.177-191<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amikura-mako-y3v1-p275-1","v":"y3v1","y":3,"o":33,"k":"spoken","w":"ichinose-honami ayanokouji-kiyotaka amikura-mako","q":"amikura mako  ever since that time  amikura s warning about ichinose at the gym after the survival exam  amikura and ichinose join him  after akiyama calls ichinose away over paperwork  amikura speaks to him alone   honami chan s really changed  huh  it s like  unimaginable when you think about how she was like a few months ago   i m telling you this because  i don t want you to make honami chan sad or hurt her   it s tough for honami chan  falling for a guy who has a girlfriend   you can t just abandon her as a friend  it s not a bad thing  understands ichinose well and watches over her   recounts the misdirected message incident that sparked rumors about ayanokoji  and asks him plainly not to hurt her  knowing she sees him as someone special  her best friend  recounts how the girls helped her through the message rumor and asks ayanokoji to protect her feelings  gym buddy  warns him not to hurt ichinose  sees he is unflustered by the blunt request","h":"<article class=\"card\" id=\"sc-amikura-mako-y3v1-p275-1\"><h3><span class=\"ttl\">&quot;Ever Since That Time…&quot;: Amikura&#x27;s warning about Ichinose<\/span><span class=\"meta\">Y3V1 · p.275–283<\/span><\/h3><p class=\"setup\">At the gym after the survival exam, Amikura and Ichinose join him; after Akiyama calls Ichinose away over paperwork, Amikura speaks to him alone.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Honami-chan&#x27;s really changed, huh? It&#x27;s like, unimaginable when you think about how she was like a few months ago…&quot;<span class=\"pg\">p.277<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m telling you this because… I don&#x27;t want you to make Honami-chan sad or hurt her.&quot;<span class=\"pg\">p.281<\/span><\/li><li class=\"q spoken\">&quot;It&#x27;s tough for Honami-chan, falling for a guy who has a girlfriend.&quot;<span class=\"pg\">p.281<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You can&#x27;t just abandon her as a friend. It&#x27;s not a bad thing.&quot;<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Understands Ichinose well and watches over her — recounts the misdirected-message incident that sparked rumors about Ayanokōji, and asks him plainly not to hurt her, knowing she sees him as someone special.<span class=\"pg\">p.275–283<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Her best friend; recounts how the girls helped her through the message rumor and asks Ayanokōji to protect her feelings.<span class=\"pg\">p.275–282<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Gym buddy; warns him not to hurt Ichinose; sees he is unflustered by the blunt request.<span class=\"pg\">p.275–283<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amikura-mako-y3v3-p182-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ninomiya-yui amikura-mako","q":"amikura mako caring for the ill ninomiya  she hasn t been feeling well since this morning  i think she s started running a fever  anxiously tends to ninomiya  placing a hand on her forehead and reporting her condition to ayanokoji and kanzaki  stays by her side as she falls ill","h":"<article class=\"card\" id=\"sc-amikura-mako-y3v3-p182-1\"><h3><span class=\"ttl\">Caring for the ill Ninomiya<\/span><span class=\"meta\">Y3V3 · p.182<\/span><\/h3><p class=\"with\">with <a href=\"ninomiya-yui.html\">Ninomiya Yui<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;She hasn&#x27;t been feeling well since this morning... I think she&#x27;s started running a fever.&quot;<span class=\"pg\">p.182<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Anxiously tends to Ninomiya, placing a hand on her forehead and reporting her condition to Ayanokōji and Kanzaki.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ninomiya Yui<\/b> Stays by her side as she falls ill.<span class=\"pg\">p.182<\/span><\/li><\/ul><\/details><\/article>"}];
